package com.smartexpense.domain.model

import java.time.Instant
import java.time.LocalDate
import java.time.YearMonth
import java.time.ZoneId

/**
 * An expected income payment. Each paycheck can cover a set of bills, which
 * lets the user see what still needs to be paid out of a specific income.
 */
data class Paycheck(
    val id: Long = 0,
    val amount: Double,
    val payDateMillis: Long,
    val label: String = "",
    val billIds: List<Long> = emptyList(),
    val createdAt: Long = 0,
    /** Set when this paycheck was generated by a recurring schedule. */
    val scheduleClientId: String? = null,
    /** Start-of-day occurrence date for a generated paycheck. */
    val occurrenceDateMillis: Long? = null,
    /**
     * True for a generated cutoff the user deleted. The row is kept as a
     * tombstone so sync cannot regenerate it.
     */
    val isSkipped: Boolean = false
) {
    /** User-facing name; falls back when the optional label is blank. */
    fun displayLabel(): String = label.ifBlank { "Paycheck" }

    /** True when this cutoff belongs to a recurring payroll schedule. */
    val isRecurringOccurrence: Boolean
        get() = scheduleClientId != null

    fun billsCovered(bills: List<Bill>): List<Bill> =
        bills.filter { it.id in billIds }

    /** Sum of the bills assigned to this paycheck. */
    fun assignedTotal(bills: List<Bill>): Double =
        billsCovered(bills).sumOf { it.amount }

    /** Paycheck amount left after covering the assigned bills. */
    fun remainingAfterBills(bills: List<Bill>): Double =
        amount - assignedTotal(bills)

    fun payDate(zoneId: ZoneId = ZoneId.systemDefault()): LocalDate =
        Instant.ofEpochMilli(payDateMillis).atZone(zoneId).toLocalDate()
}

/**
 * The first bill cycle that still needs coverage.
 *
 * A recurring bill is a single row whose due date advances every time a cycle is
 * settled, so stepping back one cycle per recorded payment recovers the first
 * cycle the user still tracks. Anchoring the cycles this way means paying a bill
 * never removes it from the paycheck that covered it; only its status changes
 * to paid.
 *
 * One-time bills keep their stored due date.
 */
fun earliestUnsettledCycleMillis(
    bill: Bill,
    paidAtMillis: List<Long> = emptyList(),
    zoneId: ZoneId = ZoneId.systemDefault()
): Long {
    if (bill.frequency == BillFrequency.NONE) return bill.dueDateMillis

    var occurrence = bill.dueDate(zoneId)
    val settledSteps = paidAtMillis.size.coerceIn(0, MAX_CYCLE_STEPS)
    var guard = 0
    while (guard < settledSteps) {
        val previousMillis = bill.previousDueDateMillis(zoneId, from = occurrence) ?: break
        occurrence = Instant.ofEpochMilli(previousMillis).atZone(zoneId).toLocalDate()
        guard++
    }

    return occurrence.atStartOfDay(zoneId).toInstant().toEpochMilli()
}

/**
 * The due date of the bill cycle a paycheck covers.
 *
 * The cycle is the newest occurrence on or before [payDateMillis], counted from
 * the first unsettled cycle. A monthly bill due on the 15th therefore shows
 * Jan 15 on January's cutoff and Feb 15 on February's, and a cycle that was
 * paid keeps its original date instead of jumping to the next one.
 *
 * One-time bills keep their stored due date.
 */
fun coveredOccurrenceDueMillis(
    bill: Bill,
    payDateMillis: Long,
    paidAtMillis: List<Long> = emptyList(),
    zoneId: ZoneId = ZoneId.systemDefault()
): Long {
    var occurrence = earliestUnsettledCycleMillis(bill, paidAtMillis, zoneId)
    if (bill.frequency == BillFrequency.NONE) return occurrence

    val payDate = Instant.ofEpochMilli(payDateMillis).atZone(zoneId).toLocalDate()
    var current = Instant.ofEpochMilli(occurrence).atZone(zoneId).toLocalDate()
    var guard = 0
    while (guard < MAX_CYCLE_STEPS) {
        val nextMillis = bill.nextDueDateMillis(zoneId, from = current) ?: break
        val next = Instant.ofEpochMilli(nextMillis).atZone(zoneId).toLocalDate()
        if (next.isAfter(payDate)) break
        current = next
        guard++
    }

    occurrence = current.atStartOfDay(zoneId).toInstant().toEpochMilli()
    return occurrence
}

/**
 * True when the cycle due on [occurrenceDueMillis] is settled.
 *
 * A recurring bill's stored due date only advances when a cycle is paid, so an
 * occurrence earlier than the stored due date means that cycle is done. A bill
 * that is currently marked paid has its latest cycle settled as well.
 *
 * The comparison happens on calendar dates: a stored due date can carry a time
 * of day (e.g. the bill form's "today" default), while cycles are normalized to
 * local midnight, so comparing raw millis would flag the current cycle as paid.
 */
fun isOccurrencePaid(
    bill: Bill,
    occurrenceDueMillis: Long,
    zoneId: ZoneId = ZoneId.systemDefault()
): Boolean {
    if (bill.isPaid) return true
    val occurrence = Instant.ofEpochMilli(occurrenceDueMillis).atZone(zoneId).toLocalDate()
    return occurrence.isBefore(bill.dueDate(zoneId))
}

/** Safety bound when stepping bill cycles backward. */
private const val MAX_CYCLE_STEPS = 600

/**
 * Window used by the Money Tracker: all past paychecks plus the current and
 * next month. Later recurring occurrences stay stored but are hidden until
 * they enter that window. The paycheck list filters by a single selected month
 * in its ViewModel instead.
 */
fun visiblePaychecks(
    paychecks: List<Paycheck>,
    nowMillis: Long = System.currentTimeMillis(),
    zoneId: ZoneId = ZoneId.systemDefault()
): List<Paycheck> {
    val lastVisibleMonth = YearMonth.from(
        Instant.ofEpochMilli(nowMillis).atZone(zoneId)
    ).plusMonths(1)

    return paychecks.filter { paycheck ->
        !YearMonth.from(paycheck.payDate(zoneId)).isAfter(lastVisibleMonth)
    }
}
